__modules["Colors"] = function()
--[[
	Colors: every colour in the template is fully saturated (QM: "top right of
	the colour picker square, only the hue changes").

	UI colours are hue(h): saturation 1, value 1.
	World colours keep saturation 1 and only lower the value where a material
	must read darker than its neighbours (dirt, trunks, leaves against grass).
	Change a value here to recolour the whole map.
]]

local Colors = {}

function Colors.hue(h: number, v: number?): Color3
	return Color3.fromHSV((h % 360) / 360, 1, v or 1)
end

local hue = Colors.hue

-- Spawn area and the walls shared by every biome
Colors.Map = {
	SpawnGround = hue(95, 0.85),
	Dirt = hue(22, 0.55),
	Grass = hue(100, 0.8),
	HitZone = hue(50, 1),
	Chevron = hue(50, 1),
	Line = Color3.new(1, 1, 1), -- the glowing edge of the hit zone
}

-- One entry per biome, in the order they run out from the hit zone.
Colors.Biomes = {
	Forest = {
		Ground = hue(115, 0.75),
		Dirt = hue(22, 0.5),
		Grass = hue(115, 0.65),
		Trunk = hue(20, 0.45),
		Leaves = { hue(125, 0.6), hue(110, 0.7), hue(135, 0.52) },
		Sign = hue(120, 1),
	},
	Savanna = {
		Ground = hue(45, 0.9),
		Dirt = hue(25, 0.6),
		Grass = hue(55, 0.85),
		Trunk = hue(22, 0.42),
		Leaves = { hue(85, 0.62), hue(75, 0.68), hue(95, 0.55) },
		Sign = hue(40, 1),
	},
}

return Colors

end

__modules["Map"] = function()
--[[
	Map: the reusable map template.

	Layout (X is the throw direction, Y up):
	  - Spawn: a 3:1 rectangle of native baseplate ground, walled in with dirt.
	  - The long +X wall has a gap in the middle. Through it is the hit zone, a
	    short yellow ledge with "HIT ZONE" and punch emojis on it and a glowing
	    white line at its edge. Past the line the ground drops away (the cliff).
	  - Below the cliff the biomes run out one after another along +X, each
	    Settings.BiomeLength long, between two long dirt walls.

	Map.build() makes Workspace.Map. Gameplay code can read:
	  Map.HitZone (part, attribute HitZone = true)
	  Map.Biomes.<Name>.Ground (attributes Biome, StartX, EndX)
]]

local Workspace = game:GetService("Workspace")
local ServerStorage = game:GetService("ServerStorage")

local Builder = __require("Builder")
local Palette = __require("Palette")
local Colors = __require("Colors")
local Trees = __require("Trees")

local Map = {}

local V3 = Vector3.new

Map.Settings = {
	SpawnDepth = 60, -- short side (X)
	SpawnLength = 180, -- long side (Z), 3:1
	WallHeight = 14,
	WallThickness = 4,
	GrassCap = 2,
	GapWidth = 40, -- the hole in the long wall
	HitZoneDepth = 24,
	Drop = 40, -- cliff height from the hit zone down to the biomes
	LaneWidth = 160,
	BiomeLength = 500,
	TreesPerBiome = 26,
	ClearPath = 26, -- no trees within this many studs of the centre line
	Biomes = { "Forest", "Savanna" },
	-- turns the HIT ZONE text so it reads from the spawn side
	TextRotation = 180,
}

-- Part from two corners (min, max) in world space.
local function slab(parent: Instance, name: string, a: Vector3, b: Vector3, color: Color3, style, opts)
	local lo = a:Min(b)
	local hi = a:Max(b)
	opts = opts or {}
	opts.name = name
	return Builder.part(parent, hi - lo, CFrame.new((lo + hi) / 2), color, style, opts)
end

-- Dirt wall with a grass cap, both in the terrain style (native grid + studs).
local function wall(parent: Instance, name: string, x0, z0, x1, z1, yBottom: number, yTop: number, pal)
	local cap = Map.Settings.GrassCap
	local m = Builder.model(name, parent)
	slab(m, "Dirt", V3(x0, yBottom, z0), V3(x1, yTop - cap, z1), pal.Dirt, "terrain")
	slab(m, "Grass", V3(x0, yTop - cap, z0), V3(x1, yTop, z1), pal.Grass, "terrain")
	return m
end

-- The place's own Baseplate is the template for every piece of ground (QM:
-- native baseplate, recoloured). It is kept in ServerStorage.TemplateSource.
local function baseplateSource(): BasePart?
	local store = ServerStorage:FindFirstChild("TemplateSource")
	local bp = store and store:FindFirstChild("Baseplate")
	if not bp then
		bp = Workspace:FindFirstChild("Baseplate")
	end
	return if bp and bp:IsA("BasePart") then bp else nil
end

local function ground(parent: Instance, name: string, x0, z0, x1, z1, topY: number, color: Color3)
	local src = baseplateSource()
	local p: BasePart
	if src then
		p = src:Clone()
		for _, c in p:GetChildren() do
			if not c:IsA("Texture") then
				c.Parent = nil
			end
		end
		local tex = p:FindFirstChildOfClass("Texture")
		if tex then
			Builder.useGridFrom(tex)
			if tex.Transparency >= 1 then
				tex.Transparency = Palette.Baseplate.TextureTransparency
			end
		end
	else
		p = Instance.new("Part")
		p.Size = V3(1, Palette.Baseplate.Thickness, 1)
		Builder.baseplateTexture(p, Palette.Baseplate)
	end
	local thick = p.Size.Y
	p.Size = V3(math.abs(x1 - x0), thick, math.abs(z1 - z0))
	p.CFrame = CFrame.new((x0 + x1) / 2, topY - thick / 2, (z0 + z1) / 2)
	p.Color = color
	p.Material = Enum.Material.Plastic
	p.Reflectance = 0
	p.Transparency = 0
	p.Anchored = true
	p.CanCollide = true
	p.Locked = false
	p.TopSurface = Enum.SurfaceType.Smooth
	p.Name = name
	p.Parent = parent
	return p
end

local function text(parent: Instance, t: string, size: UDim2, order: number)
	local l = Instance.new("TextLabel")
	l.BackgroundTransparency = 1
	l.Size = size
	l.Font = Enum.Font.FredokaOne
	l.Text = t
	l.TextScaled = true
	l.TextColor3 = Color3.new(1, 1, 1)
	l.LayoutOrder = order
	l.Parent = parent
	return l
end

-- 👊 on a dark round badge, so the yellow emoji stands out on the yellow ledge
local function punch(parent: Instance, order: number)
	local badge = Instance.new("Frame")
	badge.Name = "Punch"
	badge.Size = UDim2.fromScale(0.44, 0.44)
	badge.SizeConstraint = Enum.SizeConstraint.RelativeYY
	badge.BackgroundColor3 = Color3.new(0, 0, 0)
	badge.BackgroundTransparency = 0.3
	badge.LayoutOrder = order
	badge.Parent = parent
	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0.5, 0)
	corner.Parent = badge
	local ring = Instance.new("UIStroke")
	ring.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	ring.Thickness = 3
	ring.Color = Color3.new(1, 1, 1)
	ring.Parent = badge
	local e = text(badge, "👊", UDim2.fromScale(0.85, 0.85), 1)
	e.AnchorPoint = Vector2.new(0.5, 0.5)
	e.Position = UDim2.fromScale(0.5, 0.52)
	return badge
end

-- "👊 HIT ZONE 👊" painted on the ledge
local function hitZoneText(hz: BasePart)
	local S = Map.Settings
	-- a flat carrier part, turned so the text reads from the spawn side
	-- a Top-face SurfaceGui runs its width along the part's local Z, so the
	-- long side goes on Z when the rotation is 0/180 and on X when it is 90/270
	local across, along = S.GapWidth - 6, S.HitZoneDepth - 6
	local size = if S.TextRotation % 180 == 0 then V3(along, 0.05, across) else V3(across, 0.05, along)
	local carrier = Builder.part(hz.Parent :: Instance, size,
		hz.CFrame * CFrame.new(0, hz.Size.Y / 2 + 0.03, 0) * CFrame.Angles(0, math.rad(S.TextRotation), 0),
		Color3.new(1, 1, 1), "smooth", { name = "HitZoneText", canCollide = false, castShadow = false, transparency = 1 })
	carrier.CanQuery = false
	carrier.CanTouch = false
	local gui = Instance.new("SurfaceGui")
	gui.Name = "Text"
	gui.Face = Enum.NormalId.Top
	gui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
	gui.PixelsPerStud = 8 -- low on purpose: TextScaled tops out at 100 px, so this keeps the words big
	gui.LightInfluence = 1
	gui.Parent = carrier
	local row = Instance.new("Frame")
	row.BackgroundTransparency = 1
	row.Size = UDim2.fromScale(1, 1)
	row.Parent = gui
	local list = Instance.new("UIListLayout")
	list.FillDirection = Enum.FillDirection.Horizontal
	list.HorizontalAlignment = Enum.HorizontalAlignment.Center
	list.VerticalAlignment = Enum.VerticalAlignment.Center
	list.SortOrder = Enum.SortOrder.LayoutOrder
	list.Padding = UDim.new(0.03, 0)
	list.Parent = row
	punch(row, 1)
	local word = text(row, "HIT ZONE", UDim2.fromScale(0.58, 0.42), 2)
	local stroke = Instance.new("UIStroke")
	stroke.Thickness = 4
	stroke.Color = Color3.new(0, 0, 0)
	stroke.Transparency = 0
	stroke.LineJoinMode = Enum.LineJoinMode.Round
	stroke.Parent = word
	punch(row, 3)
	return carrier
end

-- ">" arrow on the spawn floor, pointing at the hit zone
local function chevron(parent: Instance, x: number, color: Color3)
	local m = Builder.model("Chevron", parent)
	for _, side in { -1, 1 } do
		local cf = CFrame.new(x, 0.1, side * 4) * CFrame.Angles(0, math.rad(-side * 40), 0)
		Builder.part(m, V3(3, 0.2, 12), cf, color, "studs", { name = if side < 0 then "Left" else "Right", castShadow = false })
	end
	return m
end

local function sign(parent: Instance, name: string, at: Vector3, color: Color3)
	local anchor = Builder.part(parent, V3(1, 1, 1), CFrame.new(at), color, "smooth",
		{ name = name .. "Sign", canCollide = false, castShadow = false, transparency = 1 })
	anchor.CanQuery = false
	anchor.CanTouch = false
	local gui = Instance.new("BillboardGui")
	gui.Size = UDim2.fromScale(80, 20) -- studs, so it shrinks with distance
	gui.MaxDistance = 2000
	gui.LightInfluence = 0
	gui.Parent = anchor
	local l = text(gui, name, UDim2.fromScale(1, 1), 1)
	l.TextColor3 = color
	local stroke = Instance.new("UIStroke")
	stroke.Thickness = 4
	stroke.Color = Color3.new(0, 0, 0)
	stroke.Parent = l
	return anchor
end

function Map.build(parent: Instance?)
	local S = Map.Settings
	parent = parent or Workspace
	local old = (parent :: Instance):FindFirstChild("Map")
	if old then
		old.Parent = nil
	end
	local root = Builder.model("Map", parent)
	local C = Colors.Map
	local wallPal = { Dirt = C.Dirt, Grass = C.Grass }

	local D, L, H, t = S.SpawnDepth, S.SpawnLength, S.WallHeight, S.WallThickness
	local G, HZ, Drop, W = S.GapWidth, S.HitZoneDepth, S.Drop, S.LaneWidth
	local edgeZ = math.max(L, W) / 2 + t -- outer Z of the spawn and cliff

	----------------------------------------------------------------- spawn
	local spawnM = Builder.model("Spawn", root)
	ground(spawnM, "Ground", -D - t, -L / 2 - t, 0, L / 2 + t, 0, C.SpawnGround)
	wall(spawnM, "BackWall", -D - t, -L / 2 - t, -D, L / 2 + t, 0, H, wallPal)
	wall(spawnM, "SideWallLeft", -D, -L / 2 - t, 0, -L / 2, 0, H, wallPal)
	wall(spawnM, "SideWallRight", -D, L / 2, 0, L / 2 + t, 0, H, wallPal)
	wall(spawnM, "FrontWallLeft", 0, -L / 2 - t, t, -G / 2, 0, H, wallPal)
	wall(spawnM, "FrontWallRight", 0, G / 2, t, L / 2 + t, 0, H, wallPal)
	for i = 1, 3 do
		chevron(spawnM, -30 + (i - 1) * 9, C.Chevron)
	end
	-- the place's SpawnLocation, made invisible and moved to the back of the spawn
	local sp = Workspace:FindFirstChildOfClass("SpawnLocation")
	if not sp then
		sp = Instance.new("SpawnLocation")
		sp.Parent = Workspace
	end
	sp.Anchored = true
	sp.Size = V3(12, 1, 12)
	sp.CFrame = CFrame.new(-D + 14, -0.45, 0)
	sp.Transparency = 1
	sp.CanCollide = false
	sp.Neutral = true
	for _, d in sp:GetChildren() do
		if d:IsA("Decal") then
			d.Transparency = 1
		end
	end

	--------------------------------------------------------------- hit zone
	local hzM = Builder.model("HitZone", root)
	local x0, x1 = t, t + HZ
	-- the cliff under the ledge and the raised cliff either side of the gap
	slab(hzM, "CliffFace", V3(0, -Drop, -G / 2), V3(x1, -1, G / 2), C.Dirt, "terrain")
	wall(hzM, "CliffLeft", x0, -edgeZ, x1, -G / 2, -Drop, H, wallPal)
	wall(hzM, "CliffRight", x0, G / 2, x1, edgeZ, -Drop, H, wallPal)
	local hz = slab(hzM, "Zone", V3(0, -1, -G / 2), V3(x1, 0, G / 2), C.HitZone, "terrain")
	-- under the front wall pieces either side of the gap, so they stand on something
	slab(hzM, "WallFootLeft", V3(0, -Drop, -edgeZ), V3(x0, 0, -G / 2), C.Dirt, "terrain")
	slab(hzM, "WallFootRight", V3(0, -Drop, G / 2), V3(x0, 0, edgeZ), C.Dirt, "terrain")
	hz:SetAttribute("HitZone", true)
	local line = slab(hzM, "GlowLine", V3(x1 - 1, 0, -G / 2), V3(x1, 0.2, G / 2), C.Line, "smooth",
		{ material = Enum.Material.Neon, canCollide = false, castShadow = false })
	local light = Instance.new("SurfaceLight")
	light.Face = Enum.NormalId.Top
	light.Color = C.Line
	light.Brightness = 2
	light.Range = 8
	light.Angle = 120
	light.Parent = line
	hitZoneText(hz)
	Map.HitZone = hz

	----------------------------------------------------------------- biomes
	local biomesM = Builder.model("Biomes", root)
	local laneStart = x1
	local laneEnd = laneStart + #S.Biomes * S.BiomeLength
	Map.Biomes = {}
	for i, name in S.Biomes do
		local pal = Colors.Biomes[name]
		local bx0 = laneStart + (i - 1) * S.BiomeLength
		local bx1 = bx0 + S.BiomeLength
		local bm = Builder.model(name, biomesM)
		local g = ground(bm, "Ground", bx0, -W / 2 - t, bx1, W / 2 + t, -Drop, pal.Ground)
		g:SetAttribute("Biome", name)
		g:SetAttribute("StartX", bx0)
		g:SetAttribute("EndX", bx1)
		local wp = { Dirt = pal.Dirt, Grass = pal.Grass }
		wall(bm, "WallLeft", bx0, -W / 2 - t, bx1, -W / 2, -Drop, H, wp)
		wall(bm, "WallRight", bx0, W / 2, bx1, W / 2 + t, -Drop, H, wp)
		sign(bm, name, V3(bx0 + 70, -Drop + 46, 0), pal.Sign)
		-- trees down both sides, leaving the centre clear for the ragdoll
		local decor = Builder.model("Trees", bm)
		local rng = Random.new(1000 + i)
		local n = S.TreesPerBiome
		for k = 1, n do
			local x = bx0 + 14 + (k - 0.5) * (S.BiomeLength - 28) / n + rng:NextNumber(-6, 6)
			local side = if k % 2 == 0 then 1 else -1
			local z = side * rng:NextNumber(S.ClearPath, W / 2 - 12)
			local cf = CFrame.new(x, -Drop, z) * CFrame.Angles(0, rng:NextNumber(0, math.pi * 2), 0)
			Trees.build(name, decor, cf, pal, rng)
		end
		Map.Biomes[name] = { Model = bm, Ground = g, StartX = bx0, EndX = bx1 }
	end
	wall(biomesM, "EndWall", laneEnd, -W / 2 - t, laneEnd + t, W / 2 + t, -Drop, H, wallPal)

	Map.Model = root
	return root
end

return Map

end

__modules["Sky"] = function()
--[[
	Sky: puts the free "Anime Sky" skybox from the Creator Store into Lighting.

	Only the Sky instance is taken from the model, so no scripts come along.
	Sky.AssetId pins a specific asset; left nil, the first free model whose name
	has both "anime" and "sky" is used (the id is printed so it can be pinned).
]]

local InsertService = game:GetService("InsertService")
local LightingService = game:GetService("Lighting")

local Sky = {}

Sky.AssetId = 72835926026092 :: number? -- Anime Sky by Aschorking (free)
Sky.Query = "Anime Sky"

function Sky.find(): (number?, string?)
	if Sky.AssetId then
		return Sky.AssetId, "pinned"
	end
	local ok, pages = pcall(function()
		return InsertService:GetFreeModels(Sky.Query, 0)
	end)
	if not ok or not pages or not pages[1] then
		return nil, nil
	end
	for _, r in pages[1].Results do
		local n = string.lower(r.Name)
		if string.find(n, "anime") and string.find(n, "sky") then
			return r.AssetId, r.Name .. " by " .. tostring(r.CreatorName)
		end
	end
	return nil, nil
end

function Sky.apply(): Sky?
	local id, label = Sky.find()
	if not id then
		warn("[Template] Anime Sky not found in the Creator Store; sky left as it was")
		return nil
	end
	local ok, objs = pcall(function()
		return game:GetObjects("rbxassetid://" .. id)
	end)
	if not ok or not objs then
		warn("[Template] could not load Anime Sky " .. tostring(id))
		return nil
	end
	local sky: Sky? = nil
	for _, o in objs do
		sky = if o:IsA("Sky") then o else o:FindFirstChildWhichIsA("Sky", true)
		if sky then
			break
		end
	end
	if not sky then
		warn("[Template] asset " .. tostring(id) .. " has no Sky in it")
		return nil
	end
	for _, old in LightingService:GetChildren() do
		if old:IsA("Sky") then
			old.Parent = nil
		end
	end
	sky.Name = "AnimeSky"
	sky.Parent = LightingService
	print(("[Template] sky: AnimeSky asset %d (%s)"):format(id, tostring(label)))
	return sky
end

return Sky

end

__modules["Trees"] = function()
--[[
	Trees: KISS block trees, a handful of variants per biome.

	One block per trunk or branch, foliage = one big block plus one slightly
	smaller block just above it. Every part is flat colour + QM's L-studs.
	Each builder takes (parent, origin CFrame on the ground, palette, rng)
	and returns a Model pivoted at the origin.
]]

local Builder = __require("Builder")

local Trees = {}

local V3 = Vector3.new

local function box(m: Model, origin: CFrame, center: Vector3, size: Vector3, color: Color3, name: string)
	return Builder.box(m, origin, center, size, color, "studs", { name = name })
end

-- One block running from local point a to local point b (branches, leaning trunks).
local function beam(m: Model, origin: CFrame, a: Vector3, b: Vector3, thick: number, color: Color3, name: string)
	local dir = b - a
	local up = if math.abs(dir.Unit.Y) > 0.99 then Vector3.xAxis else Vector3.yAxis
	local cf = CFrame.lookAt((a + b) / 2, b, up)
	return Builder.part(m, V3(thick, thick, dir.Magnitude), origin * cf, color, "studs", { name = name })
end

-- big block with its bottom at y, small block on top: reads as a rounded crown
local function crown(m: Model, origin: CFrame, at: Vector3, w: number, h: number, color: Color3, name: string)
	box(m, origin, at + V3(0, h / 2, 0), V3(w, h, w), color, name .. "Big")
	local sw = w * 0.7
	box(m, origin, at + V3(0, h + h * 0.25, 0), V3(sw, h * 0.5, sw), color, name .. "Top")
end

--------------------------------------------------------------------------------
-- Forest: regular trees
--------------------------------------------------------------------------------
Trees.Forest = {}

-- 1 classic: trunk + crown
Trees.Forest[1] = function(m, o, pal, leaves)
	box(m, o, V3(0, 6, 0), V3(3, 12, 3), pal.Trunk, "Trunk")
	crown(m, o, V3(0, 11, 0), 14, 8, leaves, "Leaves")
end

-- 2 tall and narrow
Trees.Forest[2] = function(m, o, pal, leaves)
	box(m, o, V3(0, 10, 0), V3(3, 20, 3), pal.Trunk, "Trunk")
	crown(m, o, V3(0, 19, 0), 11, 9, leaves, "Leaves")
end

-- 3 with one side branch carrying a small crown
Trees.Forest[3] = function(m, o, pal, leaves)
	box(m, o, V3(0, 7, 0), V3(3, 14, 3), pal.Trunk, "Trunk")
	beam(m, o, V3(0, 7, 0), V3(7, 12, 0), 2, pal.Trunk, "Branch")
	crown(m, o, V3(7, 11.5, 0), 8, 4, leaves, "BranchLeaves")
	crown(m, o, V3(0, 13, 0), 13, 7, leaves, "Leaves")
end

-- 4 short and wide
Trees.Forest[4] = function(m, o, pal, leaves)
	box(m, o, V3(0, 4, 0), V3(4, 8, 4), pal.Trunk, "Trunk")
	crown(m, o, V3(0, 7, 0), 18, 7, leaves, "Leaves")
end

--------------------------------------------------------------------------------
-- Savanna: acacias. Leaning trunk block, one block per branch, a flat slab
-- canopy (big slab + smaller slab above) at the end of each branch.
--------------------------------------------------------------------------------
Trees.Savanna = {}

local function slabCanopy(m, o, at: Vector3, w: number, d: number, color: Color3, name: string)
	box(m, o, at + V3(0, 0.8, 0), V3(w, 1.6, d), color, name .. "Big")
	box(m, o, at + V3(0, 2.2, 0), V3(w * 0.68, 1.2, d * 0.68), color, name .. "Top")
end

local function acacia(m, o, pal, leaves, lean: number, height: number, branches)
	local top = V3(lean, height, 0)
	beam(m, o, V3(0, -1, 0), top, 2.6, pal.Trunk, "Trunk")
	for i, b in branches do
		local tip = top + b.to
		-- start a little below the trunk top so the joint is buried
		beam(m, o, top - V3(0, 1, 0), tip, 1.8, pal.Trunk, "Branch" .. i)
		slabCanopy(m, o, tip - V3(0, 0.6, 0), b.w, b.d, leaves, "Canopy" .. i)
	end
end

-- 1 two branches
Trees.Savanna[1] = function(m, o, pal, leaves)
	acacia(m, o, pal, leaves, 2, 10, {
		{ to = V3(-6, 7, 2), w = 15, d = 12 },
		{ to = V3(7, 5, -3), w = 13, d = 11 },
	})
end

-- 2 three branches, wide
Trees.Savanna[2] = function(m, o, pal, leaves)
	acacia(m, o, pal, leaves, -2, 11, {
		{ to = V3(-7, 6, -2), w = 13, d = 11 },
		{ to = V3(6, 7, 4), w = 14, d = 12 },
		{ to = V3(1, 9, -6), w = 11, d = 10 },
	})
end

-- 3 one tall branch, single big canopy
Trees.Savanna[3] = function(m, o, pal, leaves)
	acacia(m, o, pal, leaves, 3, 13, {
		{ to = V3(2, 6, 0), w = 20, d = 16 },
	})
end

-- 4 short and leaning hard
Trees.Savanna[4] = function(m, o, pal, leaves)
	acacia(m, o, pal, leaves, 5, 7, {
		{ to = V3(4, 4, 1), w = 16, d = 13 },
		{ to = V3(-3, 6, -2), w = 10, d = 9 },
	})
end

function Trees.build(kind: string, parent: Instance, origin: CFrame, pal, rng: Random, variant: number?)
	local list = Trees[kind]
	local i = variant or rng:NextInteger(1, #list)
	local leaves = pal.Leaves[rng:NextInteger(1, #pal.Leaves)]
	local m = Builder.model(kind .. "Tree" .. i, parent, origin)
	list[i](m, origin, pal, leaves)
	return m
end

return Trees

end

__modules["UI"] = function()
--[[
	UI: HUD element templates in the house style.

	FredokaOne everywhere, fully saturated colours (only the hue changes), a
	black outline, QM's L-stud tile over every coloured face, white text with a
	black stroke. Self-contained, so it also works at runtime as
	ReplicatedStorage.UIKit:

	    local UIKit = require(game.ReplicatedStorage.UIKit)
	    UIKit.squareButton({ Text = "Shop", Icon = "🛒", Hue = 0, Parent = frame })
	    UIKit.rectButton({ Text = "x2 Wins", SubText = "99", Icon = "🏆", Hue = 50 })
	    UIKit.counter({ Icon = "🏆", Text = "14.09K" })
	    local modal, content = UIKit.modal({ Title = "Shop", Hue = 200 })

	Icon is an emoji or an "rbxassetid://" image. Hue is 0..360.
	Buttons with an "Opens" attribute toggle the modal of that name (see the
	HUD's controller script); every modal's "Close" button hides it.
]]

local UI = {}

UI.Font = Enum.Font.FredokaOne
UI.StudImage = "rbxassetid://100359261064701"
UI.StudTile = 26
UI.StudTransparency = 0.55
UI.Outline = Color3.new(0, 0, 0)

function UI.hue(h: number): Color3
	return Color3.fromHSV((h % 360) / 360, 1, 1)
end

local function new(class: string, props: { [string]: any }?, children: { Instance }?): any
	local o = Instance.new(class)
	local parent = nil
	for k, v in props or {} do
		if k == "Parent" then
			parent = v
		else
			(o :: any)[k] = v
		end
	end
	for _, c in children or {} do
		c.Parent = o
	end
	o.Parent = parent
	return o
end

local function corner(r: UDim?)
	return new("UICorner", { CornerRadius = r or UDim.new(0.2, 0) })
end

local function stroke(thickness: number, border: boolean?)
	return new("UIStroke", {
		Thickness = thickness,
		Color = UI.Outline,
		LineJoinMode = Enum.LineJoinMode.Round,
		ApplyStrokeMode = if border then Enum.ApplyStrokeMode.Border else Enum.ApplyStrokeMode.Contextual,
	})
end

-- White FredokaOne text with a black stroke
function UI.text(props: { [string]: any })
	local t = new("TextLabel", {
		Name = props.Name or "Label",
		BackgroundTransparency = 1,
		Font = UI.Font,
		Text = props.Text or "",
		TextColor3 = props.TextColor3 or Color3.new(1, 1, 1),
		TextScaled = true,
		TextXAlignment = props.TextXAlignment or Enum.TextXAlignment.Center,
		Size = props.Size or UDim2.fromScale(1, 1),
		Position = props.Position or UDim2.new(),
		AnchorPoint = props.AnchorPoint or Vector2.zero,
		ZIndex = props.ZIndex or 3,
		Parent = props.Parent,
	})
	stroke(props.Stroke or 2.5).Parent = t
	return t
end

-- Emoji or image icon
function UI.icon(icon: string?, props: { [string]: any })
	local common = {
		Name = "Icon",
		BackgroundTransparency = 1,
		Size = props.Size,
		Position = props.Position,
		AnchorPoint = props.AnchorPoint or Vector2.new(0.5, 0.5),
		ZIndex = 3,
		Parent = props.Parent,
	}
	if icon and string.sub(icon, 1, 3) == "rbx" then
		common.Image = icon
		common.ScaleType = Enum.ScaleType.Fit
		return new("ImageLabel", common)
	end
	common.Text = icon or ""
	common.TextScaled = true
	common.Font = UI.Font
	common.TextColor3 = Color3.new(1, 1, 1)
	return new("TextLabel", common)
end

-- Coloured face: hue fill, soft top-to-bottom shade, black outline, L-studs
function UI.face(f: GuiObject, color: Color3, radius: UDim?, outline: number?)
	f.BackgroundColor3 = color
	f.BackgroundTransparency = 0
	f.BorderSizePixel = 0
	corner(radius).Parent = f
	stroke(outline or 3, true).Parent = f
	new("UIGradient", {
		Rotation = 90,
		Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(200, 200, 200)),
	}).Parent = f
	local studs = new("ImageLabel", {
		Name = "Studs",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Image = UI.StudImage,
		ScaleType = Enum.ScaleType.Tile,
		TileSize = UDim2.fromOffset(UI.StudTile, UI.StudTile),
		ImageTransparency = UI.StudTransparency,
		ZIndex = 2,
	})
	corner(radius).Parent = studs
	studs.Parent = f
	return f
end

local function button(name: string, size: UDim2, hue: number, radius: UDim?)
	local b = new("TextButton", {
		Name = name,
		Text = "",
		AutoButtonColor = false,
		Size = size,
		ZIndex = 1,
	})
	UI.face(b, UI.hue(hue), radius)
	-- the HUD controller tweens this for hover / press
	new("UIScale", { Name = "PressScale" }).Parent = b
	return b
end

--[[ Square button: icon on top, label across the bottom edge.
	opts: Name, Text, Icon, Hue, Size (px, default 96), Parent, Opens ]]
function UI.squareButton(opts)
	local s = opts.Size or 96
	local b = button(opts.Name or "SquareButton", UDim2.fromOffset(s, s), opts.Hue or 0)
	UI.icon(opts.Icon, { Parent = b, Size = UDim2.fromScale(0.7, 0.7), Position = UDim2.fromScale(0.5, 0.42) })
	if opts.Text and opts.Text ~= "" then
		UI.text({
			Parent = b,
			Text = opts.Text,
			Size = UDim2.fromScale(1.05, 0.3),
			Position = UDim2.fromScale(0.5, 0.98),
			AnchorPoint = Vector2.new(0.5, 1),
		})
	end
	if opts.Opens then
		b:SetAttribute("Opens", opts.Opens)
	end
	b.Parent = opts.Parent
	return b
end

--[[ Rectangle button: icon on the left, title (and optional subtitle) on the right.
	opts: Name, Text, SubText, Icon, Hue, Size (UDim2, default 240x80), Parent, Opens ]]
function UI.rectButton(opts)
	local b = button(opts.Name or "RectButton", opts.Size or UDim2.fromOffset(240, 80), opts.Hue or 200, UDim.new(0.22, 0))
	UI.icon(opts.Icon, { Parent = b, Size = UDim2.fromScale(0.3, 1.05), Position = UDim2.fromScale(0.17, 0.5) })
	local hasSub = opts.SubText ~= nil and opts.SubText ~= ""
	UI.text({
		Name = "Title",
		Parent = b,
		Text = opts.Text or "Button",
		Size = UDim2.fromScale(0.64, if hasSub then 0.5 else 0.62),
		Position = UDim2.fromScale(0.33, if hasSub then 0.08 else 0.19),
	})
	if hasSub then
		UI.text({
			Name = "SubText",
			Parent = b,
			Text = opts.SubText,
			Size = UDim2.fromScale(0.64, 0.34),
			Position = UDim2.fromScale(0.33, 0.58),
			TextColor3 = UI.hue(opts.SubHue or 120),
		})
	end
	if opts.Opens then
		b:SetAttribute("Opens", opts.Opens)
	end
	b.Parent = opts.Parent
	return b
end

--[[ Counter: icon + value on a dark pill.
	opts: Name, Icon, Text, Size (UDim2, default 200x54), Parent
	Set counter.Value.Text to update it. ]]
function UI.counter(opts)
	local f = new("Frame", {
		Name = opts.Name or "Counter",
		Size = opts.Size or UDim2.fromOffset(200, 54),
		BackgroundColor3 = Color3.new(0, 0, 0),
		BackgroundTransparency = 0.45,
		BorderSizePixel = 0,
	})
	corner(UDim.new(0.5, 0)).Parent = f
	UI.icon(opts.Icon, { Parent = f, Size = UDim2.fromScale(0.3, 1.2), Position = UDim2.fromScale(0.14, 0.5) })
	UI.text({
		Name = "Value",
		Parent = f,
		Text = opts.Text or "0",
		Size = UDim2.fromScale(0.66, 0.72),
		Position = UDim2.fromScale(0.3, 0.14),
		TextXAlignment = Enum.TextXAlignment.Left,
		Stroke = 3,
	})
	f.Parent = opts.Parent
	return f
end

--[[ Modal: a general popup (shop, inventory, rebirth...).
	opts: Name, Title, Hue, Visible, Parent
	Returns the modal frame and its Content scrolling frame (a UIGridLayout is
	inside; drop cards in, or swap the layout). ]]
function UI.modal(opts)
	local m = new("Frame", {
		Name = opts.Name or "Modal",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.52),
		-- fits two rows of 150 px cards; the Content frame scrolls past that
		Size = UDim2.fromOffset(760, 440),
		Visible = opts.Visible ~= false,
		ZIndex = 10,
	})
	UI.face(m, UI.hue(opts.Hue or 200), UDim.new(0, 22), 4)
	UI.text({
		Name = "Title",
		Parent = m,
		Text = opts.Title or "Shop",
		Size = UDim2.fromOffset(420, 70),
		Position = UDim2.fromOffset(24, 0),
		AnchorPoint = Vector2.new(0, 0.5),
		TextXAlignment = Enum.TextXAlignment.Left,
		Stroke = 5,
	})
	local close = UI.squareButton({ Name = "Close", Icon = "✖", Hue = 0, Size = 64, Parent = m })
	close.AnchorPoint = Vector2.new(0.5, 0.5)
	close.Position = UDim2.new(1, -12, 0, 10)
	-- a bold white X reads better than the ✖ emoji, which renders dark
	local x = close:FindFirstChild("Icon")
	if x then
		x.Parent = nil
	end
	UI.text({
		Name = "Icon",
		Parent = close,
		Text = "X",
		Size = UDim2.fromScale(0.62, 0.62),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Stroke = 3,
	})
	local body = new("Frame", {
		Name = "Body",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -22),
		Size = UDim2.new(1, -44, 1, -86),
		BackgroundColor3 = Color3.new(0, 0, 0),
		BackgroundTransparency = 0.72,
		ZIndex = 3,
		Parent = m,
	})
	corner(UDim.new(0, 16)).Parent = body
	local content = new("ScrollingFrame", {
		Name = "Content",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ScrollBarThickness = 8,
		ScrollBarImageColor3 = Color3.new(1, 1, 1),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		CanvasSize = UDim2.new(),
		ZIndex = 4,
		Parent = body,
	})
	new("UIPadding", {
		PaddingTop = UDim.new(0, 16),
		PaddingBottom = UDim.new(0, 16),
		PaddingLeft = UDim.new(0, 16),
		PaddingRight = UDim.new(0, 16),
		Parent = content,
	})
	new("UIGridLayout", {
		CellSize = UDim2.fromOffset(150, 150),
		CellPadding = UDim2.fromOffset(16, 16),
		HorizontalAlignment = Enum.HorizontalAlignment.Center,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = content,
	})
	m.Parent = opts.Parent
	return m, content
end

--[[ Shop / inventory card for a modal: square button with a price under the label.
	opts: Name, Text, Icon, Hue, Price, Parent ]]
function UI.card(opts)
	local c = UI.squareButton({ Name = opts.Name or "Card", Text = opts.Text, Icon = opts.Icon, Hue = opts.Hue, Size = 150 })
	local icon = c:FindFirstChild("Icon")
	if icon then
		icon.Size = UDim2.fromScale(0.56, 0.56)
		icon.Position = UDim2.fromScale(0.5, 0.36)
	end
	local label = c:FindFirstChild("Label")
	if label then
		label.Size = UDim2.fromScale(0.95, 0.2)
		label.Position = UDim2.fromScale(0.5, 0.82)
	end
	if opts.Price then
		UI.text({
			Name = "Price",
			Parent = c,
			Text = opts.Price,
			Size = UDim2.fromScale(0.9, 0.18),
			Position = UDim2.fromScale(0.5, 0.99),
			AnchorPoint = Vector2.new(0.5, 1),
			TextColor3 = UI.hue(120),
		})
	end
	c.Parent = opts.Parent
	return c
end

-- LocalScript placed in the demo HUD: scales the HUD to the screen, animates
-- every button, and wires Opens / Close.
UI.ControllerSource = [[
local TweenService = game:GetService("TweenService")
local gui = script.Parent
local camera = workspace.CurrentCamera

local autoScale = gui:FindFirstChild("AutoScale")
local function rescale()
	if autoScale then
		autoScale.Scale = math.clamp(camera.ViewportSize.Y / 820, 0.55, 1.3)
	end
end
camera:GetPropertyChangedSignal("ViewportSize"):Connect(rescale)
rescale()

local function hook(b)
	if not b:IsA("GuiButton") then
		return
	end
	local s = b:FindFirstChild("PressScale")
	if s then
		local function to(v)
			TweenService:Create(s, TweenInfo.new(0.08, Enum.EasingStyle.Quad), { Scale = v }):Play()
		end
		b.MouseEnter:Connect(function() to(1.06) end)
		b.MouseLeave:Connect(function() to(1) end)
		b.MouseButton1Down:Connect(function() to(0.92) end)
		b.MouseButton1Up:Connect(function() to(1.06) end)
	end
	local opens = b:GetAttribute("Opens")
	if opens then
		b.Activated:Connect(function()
			local m = gui:FindFirstChild(opens, true)
			if m then
				m.Visible = not m.Visible
			end
		end)
	end
	if b.Name == "Close" and b.Parent and b.Parent:IsA("GuiObject") then
		b.Activated:Connect(function()
			b.Parent.Visible = false
		end)
	end
end

for _, d in gui:GetDescendants() do
	hook(d)
end
gui.DescendantAdded:Connect(hook)
]]

-- A HUD laid out with every template, as a starting point for each game.
function UI.buildHUD(parent: Instance, modalVisible: boolean?)
	local old = parent:FindFirstChild("HUD")
	if old then
		old.Parent = nil
	end
	local gui = new("ScreenGui", {
		Name = "HUD",
		ResetOnSpawn = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
	})
	new("UIScale", { Name = "AutoScale", Parent = gui })

	-- left: counters over a 2-wide grid of square buttons
	local left = new("Frame", {
		Name = "Left",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 20, 0.5, 0),
		Size = UDim2.fromOffset(212, 470),
		Parent = gui,
	})
	new("UIListLayout", { Padding = UDim.new(0, 12), SortOrder = Enum.SortOrder.LayoutOrder, Parent = left })
	local c1 = UI.counter({ Name = "Rebirths", Icon = "🔁", Text = "2", Parent = left })
	c1.LayoutOrder = 1
	local c2 = UI.counter({ Name = "Wins", Icon = "🏆", Text = "14.09K", Parent = left })
	c2.LayoutOrder = 2
	local grid = new("Frame", {
		Name = "Buttons",
		BackgroundTransparency = 1,
		Size = UDim2.fromOffset(212, 330),
		LayoutOrder = 3,
		Parent = left,
	})
	new("UIGridLayout", {
		CellSize = UDim2.fromOffset(96, 96),
		CellPadding = UDim2.fromOffset(14, 14),
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = grid,
	})
	local squares = {
		{ "Shop", "🛒", 0, "ShopModal" },
		{ "Rebirth", "🔁", 200 },
		{ "Pets", "🐾", 30 },
		{ "Auras", "✨", 285 },
		{ "Trails", "💫", 260 },
		{ "Gifts", "🎁", 330 },
	}
	for i, s in squares do
		local b = UI.squareButton({ Name = s[1], Text = s[1], Icon = s[2], Hue = s[3], Opens = s[4], Parent = grid })
		b.LayoutOrder = i
	end

	-- right: rectangle buttons
	local right = new("Frame", {
		Name = "Right",
		BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -20, 0.5, 0),
		Size = UDim2.fromOffset(240, 280),
		Parent = gui,
	})
	new("UIListLayout", { Padding = UDim.new(0, 14), SortOrder = Enum.SortOrder.LayoutOrder, Parent = right })
	local rects = {
		{ "x1.5 Skill", "1", "⚡", 30 },
		{ "x2 Wins", "99", "🏆", 50 },
		{ "Auto Throw", "79", "🎯", 200 },
	}
	for i, r in rects do
		local b = UI.rectButton({ Name = r[1], Text = r[1], SubText = r[2], Icon = r[3], Hue = r[4], Parent = right })
		b.LayoutOrder = i
	end

	-- bottom centre: skill counter
	local skill = UI.counter({ Name = "Skill", Icon = "⚡", Text = "1.23K", Parent = gui })
	skill.AnchorPoint = Vector2.new(0.5, 1)
	skill.Position = UDim2.new(0.5, 0, 1, -24)

	-- the general modal, here as a shop
	local modal, content = UI.modal({ Name = "ShopModal", Title = "Shop", Hue = 200, Visible = modalVisible == true, Parent = gui })
	local items = {
		{ "Sword", "🗡️", 0, "50" },
		{ "Bat", "🏏", 30, "120" },
		{ "Hammer", "🔨", 55, "300" },
		{ "Rocket", "🚀", 200, "900" },
		{ "Magnet", "🧲", 285, "2K" },
		{ "Bomb", "💣", 330, "5K" },
		{ "Star", "⭐", 175, "10K" },
		{ "Crown", "👑", 120, "50K" },
	}
	for i, it in items do
		local c = UI.card({ Name = it[1], Text = it[1], Icon = it[2], Hue = it[3], Price = it[4], Parent = content })
		c.LayoutOrder = i
	end
	modal.ZIndex = 10

	local controller = Instance.new("LocalScript")
	controller.Name = "HUDController"
	;(controller :: any).Source = UI.ControllerSource
	controller.Parent = gui

	gui.Parent = parent
	return gui
end

-- Bare templates to :Clone() from code (ReplicatedStorage.UITemplates).
function UI.buildTemplates(parent: Instance)
	local old = parent:FindFirstChild("UITemplates")
	if old then
		old.Parent = nil
	end
	local folder = new("Folder", { Name = "UITemplates" })
	UI.squareButton({ Name = "SquareButton", Text = "Button", Icon = "⭐", Hue = 0, Parent = folder })
	UI.rectButton({ Name = "RectButton", Text = "Button", SubText = "99", Icon = "⭐", Hue = 200, Parent = folder })
	UI.counter({ Name = "Counter", Icon = "🏆", Text = "0", Parent = folder })
	UI.modal({ Name = "Modal", Title = "Title", Hue = 200, Parent = folder })
	UI.card({ Name = "Card", Text = "Item", Icon = "⭐", Hue = 50, Price = "10", Parent = folder })
	folder.Parent = parent
	return folder
end

return UI

end

__modules["Template"] = function()
--[[
	Template: the reusable map + HUD template.

	    Template.build()  -- lighting + Anime Sky, Workspace.Map, StarterGui.HUD,
	                      -- ReplicatedStorage.UITemplates and ReplicatedStorage.UIKit

	Map.Settings and Colors hold every size and colour; Trees holds the
	per-biome tree variants; UI holds the HUD element builders.
]]

local Workspace = game:GetService("Workspace")
local ServerStorage = game:GetService("ServerStorage")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local StarterGui = game:GetService("StarterGui")

local Template = {}

Template.Colors = __require("Colors")
Template.Trees = __require("Trees")
Template.Map = __require("Map")
Template.UI = __require("UI")
Template.Sky = __require("Sky")
Template.Lighting = __require("Lighting")

-- Old showcase content and the original Baseplate move to ServerStorage so the
-- map has the place to itself (nothing is deleted).
local function tidy()
	local store = ServerStorage:FindFirstChild("TemplateSource")
	if not store then
		store = Instance.new("Folder")
		store.Name = "TemplateSource"
		store.Parent = ServerStorage
	end
	local bp = Workspace:FindFirstChild("Baseplate")
	if bp and not store:FindFirstChild("Baseplate") then
		bp.Parent = store
	end
	local show = Workspace:FindFirstChild("AssetShowcase")
	if show then
		show.Parent = store
	end
end

-- uiSource: the UI module's own source, so it can also live in the place as a
-- ModuleScript (the bundled command-bar script passes it in)
function Template.build(uiSource: string?)
	local L = Template.Lighting
	L.SkyAsset = nil
	L.ColorCorrection.Saturation = 0 -- colours are already fully saturated
	L.apply()
	Template.Sky.apply()

	Template.Map.build(Workspace)
	tidy()

	Template.UI.buildHUD(StarterGui)
	Template.UI.buildTemplates(ReplicatedStorage)
	if uiSource then
		local old = ReplicatedStorage:FindFirstChild("UIKit")
		if old then
			old.Parent = nil
		end
		local mod = Instance.new("ModuleScript")
		mod.Name = "UIKit"
		;(mod :: any).Source = uiSource
		mod.Parent = ReplicatedStorage
	end
end

return Template

end

__modules["Builder"] = function()
--[[
	Builder: low-level helpers for the studded blocky style.

	All parts are anchored matte SmoothPlastic in one flat colour, with QM's stud
	texture on every face ("studs"), an Inlet top ("inlet"), or no detail ("smooth"). Positions are given in the local
	space of an origin CFrame, so every asset can be built at any spot and rotation.
]]

local Palette = __require("Palette")

local Builder = {}

-- The grid texture laid over every studded face. It starts as the settings in
-- Palette.Baseplate and is replaced by the place's own Baseplate texture when
-- one exists (Builder.useGridFrom), so blocks get the same native checker grid.
Builder.Grid = {
	Texture = Palette.Baseplate.Texture,
	StudsPerTileU = Palette.Baseplate.StudsPerTile,
	StudsPerTileV = Palette.Baseplate.StudsPerTile,
	Transparency = Palette.Baseplate.TextureTransparency,
	Color3 = Palette.Baseplate.TextureColor,
}

function Builder.useGridFrom(tex: Texture)
	Builder.Grid = {
		Texture = tex.Texture,
		StudsPerTileU = tex.StudsPerTileU,
		StudsPerTileV = tex.StudsPerTileV,
		Transparency = if tex.Transparency >= 1 then Palette.Baseplate.TextureTransparency else tex.Transparency,
		Color3 = tex.Color3,
	}
end

-- QM's L-stud texture (Figma stud tile, same asset FightToStealAnEgg uses for
-- its HUD). Mostly transparent, so the part's own flat colour shows through.
-- One tile is 4x4 studs.
Builder.Studs = {
	Texture = "rbxassetid://100359261064701",
	StudsPerTile = 4,
	-- softens the L shadow so it reads like the reference instead of popping
	Transparency = 0.35,
}

local NORMALS = { Enum.NormalId.Top, Enum.NormalId.Bottom, Enum.NormalId.Left, Enum.NormalId.Right, Enum.NormalId.Front, Enum.NormalId.Back }

function Builder.addGrid(p: BasePart)
	local g = Builder.Grid
	for _, face in NORMALS do
		local t = Instance.new("Texture")
		-- unique names: Rojo can drop siblings that share a name when it syncs
		t.Name = "Grid" .. face.Name
		t.Face = face
		t.Texture = g.Texture
		t.StudsPerTileU = g.StudsPerTileU
		t.StudsPerTileV = g.StudsPerTileV
		t.Transparency = g.Transparency
		t.Color3 = g.Color3
		t.Parent = p
	end
end

-- Light-reactive studs: a MaterialVariant whose normal map (assets/studs, made
-- by tools/make_stud_maps.py) gives bright rims in sun and flat studs in shadow.
-- Decals can't react to light. Fill in the uploaded ids to switch every studded
-- part over; until then the decal is used.
Builder.StudMaterial = {
	Name = "AssetKitStuds",
	ColorMap = "", -- rbxassetid of assets/studs/stud_color.png
	NormalMap = "", -- rbxassetid of assets/studs/stud_normal.png
	StudsPerTile = 4,
}

local function studVariant(): string?
	local m = Builder.StudMaterial
	if m.ColorMap == "" or m.NormalMap == "" then
		return nil
	end
	local ms = game:GetService("MaterialService")
	if not ms:FindFirstChild(m.Name) then
		local v = Instance.new("MaterialVariant")
		v.Name = m.Name
		v.BaseMaterial = Enum.Material.SmoothPlastic
		v.ColorMap = m.ColorMap
		v.NormalMap = m.NormalMap
		v.StudsPerTile = m.StudsPerTile
		v.Parent = ms
	end
	return m.Name
end

function Builder.addStuds(p: BasePart)
	local variant = studVariant()
	if variant then
		p.Material = Enum.Material.SmoothPlastic
		p.MaterialVariant = variant
		return
	end
	local st = Builder.Studs
	for _, face in NORMALS do
		local t = Instance.new("Texture")
		t.Name = "Studs" .. face.Name
		t.Face = face
		t.Texture = st.Texture
		t.StudsPerTileU = st.StudsPerTile
		t.StudsPerTileV = st.StudsPerTile
		t.Transparency = st.Transparency
		-- white keeps the tile's rim highlight (QM wants it in sunlight; the
		-- engine's lighting dims it in shadow). Transparency keeps it from glowing.
		t.Color3 = Color3.new(1, 1, 1)
		t.Parent = p
	end
end

local FACES = { "TopSurface", "BottomSurface", "LeftSurface", "RightSurface", "FrontSurface", "BackSurface" }

-- "terrain": studs plus the native baseplate grid (walls, cliffs)
-- "studs": studs only, flat colour (trees, bushes, small obstacles)
type Style = "terrain" | "studs" | "inlet" | "smooth"

-- f > 0 lightens towards white, f < 0 darkens towards black.
function Builder.shade(c: Color3, f: number): Color3
	if f >= 0 then
		return c:Lerp(Color3.new(1, 1, 1), f)
	end
	return c:Lerp(Color3.new(0, 0, 0), -f)
end

function Builder.jitter(c: Color3, rng: Random, amount: number): Color3
	return Builder.shade(c, (rng:NextNumber() * 2 - 1) * amount)
end

function Builder.pick(list: { any }, rng: Random): any
	return list[rng:NextInteger(1, #list)]
end

function Builder.model(name: string, parent: Instance?, pivot: CFrame?): Model
	local m = Instance.new("Model")
	m.Name = name
	if pivot then
		m.WorldPivot = pivot
	end
	m.Parent = parent
	return m
end

function Builder.applyStyle(p: BasePart, style: Style?)
	style = style or "studs"
	-- studs come from QM's stud texture, not Roblox's SurfaceType.Studs
	for _, face in FACES do
		(p :: any)[face] = Enum.SurfaceType.Smooth
	end
	if style == "inlet" then
		p.TopSurface = Enum.SurfaceType.Inlet
	end
	-- obstacles are flat colour with studs only (QM): no grid texture, no checker.
	if style == "studs" or style == "terrain" then
		Builder.addStuds(p)
	end
	if style == "terrain" then
		-- walls and cliffs also carry the native baseplate grid
		Builder.addGrid(p)
	end
end

type PartOpts = {
	class: string?,
	name: string?,
	material: Enum.Material?,
	canCollide: boolean?,
	castShadow: boolean?,
	transparency: number?,
}

-- Raw part at a world CFrame.
function Builder.part(parent: Instance, size: Vector3, cf: CFrame, color: Color3, style: Style?, opts: PartOpts?): BasePart
	local o: PartOpts = opts or {}
	local p = Instance.new(o.class or "Part") :: BasePart
	p.Anchored = true
	p.Size = size
	p.CFrame = cf
	p.Color = color
	-- matte everywhere: flat SmoothPlastic with no reflectance
	p.Material = o.material or Enum.Material.SmoothPlastic
	p.Reflectance = 0
	Builder.applyStyle(p, style)
	p.CanCollide = o.canCollide ~= false
	p.CastShadow = o.castShadow ~= false
	if o.transparency then
		p.Transparency = o.transparency
	end
	-- unique sibling names keep Rojo syncs reliable
	p.Name = o.name or ("Block" .. (#parent:GetChildren() + 1))
	p.Parent = parent
	return p
end

-- Part centred at a local position relative to origin.
function Builder.box(parent: Instance, origin: CFrame, center: Vector3, size: Vector3, color: Color3, style: Style?, opts: PartOpts?): BasePart
	return Builder.part(parent, size, origin * CFrame.new(center), color, style, opts)
end

-- Part whose bottom face sits at local y = bottom.
function Builder.block(parent: Instance, origin: CFrame, x: number, bottom: number, z: number, size: Vector3, color: Color3, style: Style?, opts: PartOpts?): BasePart
	return Builder.box(parent, origin, Vector3.new(x, bottom + size.Y / 2, z), size, color, style, opts)
end

-- The texture the default Studio baseplate uses, applied to the top face.
function Builder.baseplateTexture(p: BasePart, settings)
	local t = Instance.new("Texture")
	t.Name = "BaseplateGrid"
	t.Face = Enum.NormalId.Top
	t.Texture = settings.Texture
	t.StudsPerTileU = settings.StudsPerTile
	t.StudsPerTileV = settings.StudsPerTile
	t.Transparency = settings.TextureTransparency
	t.Color3 = settings.TextureColor
	t.Parent = p
	return t
end

-- Floating name tag used by the showcase.
function Builder.label(adornee: Instance, text: string, height: number)
	local gui = Instance.new("BillboardGui")
	gui.Name = "ShowcaseLabel"
	gui.Size = UDim2.fromOffset(220, 40)
	gui.StudsOffsetWorldSpace = Vector3.new(0, height, 0)
	gui.AlwaysOnTop = true
	gui.MaxDistance = 160
	gui.Adornee = adornee
	local tl = Instance.new("TextLabel")
	tl.Size = UDim2.fromScale(1, 1)
	tl.BackgroundTransparency = 1
	tl.Font = Enum.Font.FredokaOne
	tl.TextScaled = true
	tl.TextColor3 = Color3.new(1, 1, 1)
	tl.TextStrokeTransparency = 0
	tl.Text = text
	tl.Parent = gui
	gui.Parent = adornee
	return gui
end

return Builder

end

